public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    int numVertices = 0;
    Map<Integer, HashSet<Integer>> adjacencyMap = new HashMap<>();

    for (V vertex : target.getNodes()) {
        resultMap.put(vertex.toString(), new V());
        numVertices++;
    }

    for (int i = 0; i < numVertices; i++) {
        int numEdges = numVertices - i - 1;
        HashSet<Integer> neighbors = new HashSet<>();

        for (int j = 0; j < numEdges; j++) {
            int neighbor = i + j + 2;
            if (neighbor >= numVertices) {
                neighbor = i + j + 2 - numVertices;
            }
            neighbors.add(resultMap.get(neighbor.toString()));
        }

        adjacencyMap.put(resultMap.get(vertex.toString()), neighbors);
    }
}

