                // If bucket 0 becomes empty, remove it from the bucketsByLabel list
                bucketsByLabel.remove(bucket);
            } else {
                // Update labels of vertices in bucket 0
                for (int vertex : bucket) {
                    labels.set(vertex, 0);
                }
            }
        }
    }
}

